use crate::wasi::clocks::wall_clock;

struct Node;

/// Converts days since 1970-01-01 to (year, month, day) in the proleptic
/// Gregorian calendar (Howard Hinnant's `civil_from_days`), using unsigned
/// arithmetic since the input is never negative.
fn civil_from_days(days: u64) -> (u64, u64, u64) {
    let z = days + 719_468;
    let era = z / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = if m <= 2 { y + 1 } else { y };
    (y, m, d)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        let days = now.seconds / 86_400;
        let (y, m, d) = civil_from_days(days);

        // The contract requires a 10-character date, which only holds for
        // years 0000..=9999. Fail closed rather than emit a malformed date.
        assert!(y <= 9_999, "clock outside the 4-digit date range");

        RunInfo {
            date: format!("{:04}-{:02}-{:02}", y, m, d),
            started: now.seconds,
        }
    }
}

export!(Node);
